// Tüm sayfaların extraction sonuçlarını tek bir current-run yapısında birleştirir ve doğrular.
// Şablondaki "Normalize Price Values" mantığı ($ temizleyip sayıya çevirme) korunmuştur.
// 0 ürün / doğrulama hatasında da tek bir özet item döner; akış sessizce kaybolmaz.
const SOURCE_URL = 'https://webscraper.io/test-sites/e-commerce/static/computers/laptops';
const BASE = 'https://webscraper.io';
const runTs = new Date().toISOString();
const asArray = (v) => (Array.isArray(v) ? v : v === undefined || v === null || v === '' ? [] : [v]);

// Not: n8n Code sandbox'ında URL sınıfı tanımlı değil; mutlak link string işlemleriyle üretilir.
const toAbsoluteLink = (href) => {
  const h = String(href ?? '').trim();
  let abs;
  if (/^https?:\/\//i.test(h)) abs = h;
  else if (h.startsWith('//')) abs = 'https:' + h;
  else if (h.startsWith('/')) abs = BASE + h;
  else return null;
  abs = abs.split('#')[0].split('?')[0].replace(/\/+$/, '').replace(/^http:\/\//i, 'https://');
  return /^https:\/\/webscraper\.io\/\S+$/i.test(abs) ? abs : null;
};

const errors = [];
const byKey = new Map();
let rawCount = 0;
let duplicateCount = 0;
let expectedCount = null;

const pages = $input.all();
pages.forEach((item, index) => {
  const page = index + 1;
  const j = item.json;
  const names = asArray(j.product_name);
  const prices = asArray(j.price_raw);
  const reviews = asArray(j.review_raw);
  const links = asArray(j.product_href);
  if (expectedCount === null) {
    const m = String(j.item_count_text || '').match(/(\d+)\s+items?/i);
    if (m) expectedCount = Number(m[1]);
  }
  const n = names.length;
  if (prices.length !== n || reviews.length !== n || links.length !== n) {
    errors.push(`Sayfa ${page}: liste uzunlukları uyuşmuyor (ad ${n}, fiyat ${prices.length}, yorum ${reviews.length}, link ${links.length})`);
    return;
  }
  for (let k = 0; k < n; k++) {
    rawCount++;
    const name = String(names[k] ?? '').trim();
    const priceText = String(prices[k] ?? '').replace(/[$,\s]/g, '');
    const price = /^\d+(\.\d+)?$/.test(priceText) ? Number(priceText) : NaN;
    const reviewText = String(reviews[k] ?? '').replace(/\D/g, '');
    const reviewCount = reviewText === '' ? NaN : Number(reviewText);
    const link = toAbsoluteLink(links[k]);
    if (!name || !Number.isFinite(price) || !Number.isInteger(reviewCount) || !link) {
      errors.push(`Sayfa ${page}, ürün ${k + 1}: geçersiz ad/fiyat/yorum/link`);
      continue;
    }
    if (byKey.has(link)) {
      duplicateCount++;
      continue;
    }
    byKey.set(link, { product_key: link, product_name: name, price, review_count: reviewCount, product_link: link });
  }
});

const products = [...byKey.values()];
if (expectedCount !== null && products.length !== expectedCount) {
  errors.push(`Sitedeki ürün sayısı (${expectedCount}) ile çıkarılan benzersiz ürün sayısı (${products.length}) uyuşmuyor`);
}

return [{
  json: {
    run_ts: runTs,
    source_url: SOURCE_URL,
    page_count: pages.length,
    raw_count: rawCount,
    product_count: products.length,
    expected_count: expectedCount,
    duplicate_count: duplicateCount,
    valid: errors.length === 0 && products.length > 0,
    errors: errors.slice(0, 10),
    products,
  },
}];

// Şablondaki "Compute Price Change" mantığı (önceki/güncel fiyat + % fark) Data Table geçmişine uyarlandı.
// Karşılaştırma, güncel snapshot tabloya yazılmadan ÖNCE yapılır.
const current = $('Normalize & Validate').first().json;
// İlk çalıştırmada tablo boşsa Get Previous Snapshot boş bir item döner; product_key'i olmayanlar yok sayılır.
const previousRows = $input.all().map((i) => i.json).filter((r) => r && typeof r.product_key === 'string' && r.product_key);
const cents = (v) => Math.round(Number(v) * 100);
const ts = (r) => {
  const t = Date.parse(String(r.run_ts));
  return Number.isFinite(t) ? t : 0;
};

// Append-only tabloda her product_key için EN GÜNCEL önceki kaydı bul (run_ts; eşitlikte satır id'si).
const latest = new Map();
for (const row of previousRows) {
  const prev = latest.get(row.product_key);
  if (!prev || ts(row) > ts(prev) || (ts(row) === ts(prev) && Number(row.id || 0) > Number(prev.id || 0))) {
    latest.set(row.product_key, row);
  }
}

return current.products.map((p) => {
  const prev = latest.get(p.product_key);
  const previousPrice = prev ? Number(prev.price) : null;
  let status = 'NEW';
  if (prev) status = cents(previousPrice) !== cents(p.price) ? 'PRICE_CHANGED' : 'NO_CHANGE';
  const priceDiffPct = prev && previousPrice ? Number((((p.price - previousPrice) / previousPrice) * 100).toFixed(2)) : null;
  return {
    json: {
      status,
      product_key: p.product_key,
      product_name: p.product_name,
      price: p.price,
      previous_price: previousPrice,
      price_diff_pct: priceDiffPct,
      review_count: p.review_count,
      product_link: p.product_link,
      run_ts: current.run_ts,
      previous_run_ts: prev ? prev.run_ts : null,
    },
  };
});

// Şablondaki "Build Telegram Alert Message" fikri korunur; ürün başına mesaj yerine tek, kısa özet mesaj üretilir.
// Buraya yalnız NEW / PRICE_CHANGED ürünler gelir.
const changed = $input.all().map((i) => i.json);
if (changed.length === 0) return [];
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (n) => `$${Number(n).toFixed(2)}`;
const MAX = 5;
const news = changed.filter((c) => c.status === 'NEW');
const priceChanged = changed.filter((c) => c.status === 'PRICE_CHANGED');

const lines = [
  '🛒 Laptop fiyat takibi — değişiklik bildirimi',
  `Zaman: ${changed[0].run_ts}`,
  `Yeni ürün: ${news.length} · Fiyatı değişen: ${priceChanged.length}`,
];
if (priceChanged.length) {
  lines.push('', '💲 Fiyatı değişenler:');
  for (const c of priceChanged.slice(0, MAX)) {
    const sign = c.price_diff_pct > 0 ? '+' : '';
    lines.push(`• ${esc(c.product_name)}: ${fmt(c.previous_price)} → ${fmt(c.price)} (${sign}${c.price_diff_pct}%)`);
  }
  if (priceChanged.length > MAX) lines.push(`… ve ${priceChanged.length - MAX} ürün daha`);
}
if (news.length) {
  lines.push('', '🆕 Yeni ürünler:');
  for (const c of news.slice(0, MAX)) lines.push(`• ${esc(c.product_name)} — ${fmt(c.price)}`);
  if (news.length > MAX) lines.push(`… ve ${news.length - MAX} ürün daha`);
}
lines.push('', 'Kaynak: https://webscraper.io/test-sites/e-commerce/static/computers/laptops');

return [{ json: { message: lines.join('\n'), new_count: news.length, price_changed_count: priceChanged.length } }];

// Hata dalı: (A) Fetch All Laptop Pages hata çıkışı — site açılamadı / HTTP / ağ / timeout
//            (B) Has Valid Products? = false — 0 ürün veya doğrulama hatası
const SOURCE_URL = 'https://webscraper.io/test-sites/e-commerce/static/computers/laptops';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const j = $input.first().json;
let reason;
let detail;
if ('product_count' in j) {
  if (j.product_count === 0) {
    reason = 'ZERO_PRODUCTS';
    detail = '0 ürün çıkarıldı';
  } else {
    reason = 'VALIDATION_FAILED';
    detail = `${j.product_count} ürün çıkarıldı ancak doğrulama başarısız`;
  }
  if (Array.isArray(j.errors) && j.errors.length) detail += ` — ${j.errors.slice(0, 3).join(' | ')}`;
} else {
  reason = 'SITE_UNREACHABLE';
  const e = j.error;
  let msg;
  // HTTP hata kodunda error.statusCode gelir (gövde HTML'dir, mesaja eklenmez); ağ/DNS/timeout hatasında error.message.
  if (e && typeof e === 'object' && e.statusCode) msg = `HTTP ${e.statusCode}`;
  else if (typeof e === 'string') msg = e;
  else msg = (e && (e.message || e.description)) || 'bilinmeyen hata';
  detail = `Site açılamadı / HTTP hatası: ${String(msg).slice(0, 200)}`;
}
const failedAt = new Date().toISOString();
const message = [
  '⚠️ Laptop fiyat takibi BAŞARISIZ',
  `Neden: ${reason}`,
  `Detay: ${esc(detail)}`,
  `Kaynak: ${SOURCE_URL}`,
  `Zaman: ${failedAt}`,
  `Execution: ${$execution.id}`,
].join('\n');
return [{ json: { reason, detail, source_url: SOURCE_URL, failed_at: failedAt, message } }];
